      'invalid service data',
      JSON.stringify({
        schemaVersion: 1,
        exportedAt: new Date().toISOString(),
        services: [{ id: 'broken' }],
        hosts: [],
      }),
    ],
  ])('rejects %s', (_label, input) => {
    expect(() => parseImport(input)).toThrow()
  })
})

